18 | import {ReentrancyGuard} from "@rari-capital/solmate/src/utils/ReentrancyGuard.sol";
19 | import {SafeTransferLib} from "@rari-capital/solmate/src/utils/SafeTransferLib.sol";
20 | 
21 | /*
22 | 	Data Storage Schema
23 | 	NodeIDs are 20 bytes so can use Solidity 'address' as storage type for them
24 | 	NodeIDs can be added, but never removed. If a nodeID submits another validation request,
25 | 		it will overwrite the old one (only allowed for specific statuses).
26 | 
27 | 	MinipoolManager.TotalAVAXLiquidStakerAmt = total for all active minipools (Prelaunch/Launched/Staking)
28 | 
29 | 	minipool.count = Starts at 0 and counts up by 1 after a node is added.
30 | 
31 | 	minipool.index<nodeID> = <index> of nodeID
32 | 	minipool.item<index>.nodeID = nodeID used as primary key (NOT the ascii "Node-123..." but the actual 20 bytes)
33 | 	minipool.item<index>.status = enum
34 | 	minipool.item<index>.duration = requested validation duration in seconds (performed as 14 day cycles)
35 | 	minipool.item<index>.delegationFee = node operator specified fee (must be between 0 and 1 ether) 2% is 0.2 ether
36 | 	minipool.item<index>.owner = owner address
37 | 	minipool.item<index>.multisigAddr = which Rialto multisig is assigned to manage this validation
38 | 	minipool.item<index>.avaxNodeOpAmt = avax deposited by node operator (for this cycle)
39 | 	minipool.item<index>.avaxNodeOpInitialAmt = avax deposited by node operator for the **first** validation cycle
40 | 	minipool.item<index>.avaxLiquidStakerAmt = avax deposited by users and assigned to this nodeID
41 | 
42 | 	// Submitted by the Rialto oracle
43 | 	minipool.item<index>.txID = transaction id of the AddValidatorTx
44 | 	minipool.item<index>.initialStartTime = actual time the **first** validation cycle was started
45 | 	minipool.item<index>.startTime = actual time validation was started
46 | 	minipool.item<index>.endTime = actual time validation was finished
47 | 	minipool.item<index>.avaxTotalRewardAmt = Actual total avax rewards paid by avalanchego to the TSS P-chain addr
48 | 	minipool.item<index>.errorCode = bytes32 that encodes an error msg if something went wrong during launch of minipool
49 | 
50 | 	// Calculated in recordStakingEnd()
51 | 	minipool.item<index>.avaxNodeOpRewardAmt
52 | 	minipool.item<index>.avaxLiquidStakerRewardAmt
